# components 4-neighbor
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c] and (r,c) not in seen:
   col=grid[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
   while st:
    x,y=st.pop(); cells.append((x,y))
    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=a<R and 0<=b<C and grid[a][b]==col and (a,b) not in seen:seen.add((a,b));st.append((a,b))
   comps.append(cells)
# rightmost first, each rigid translate maximum; collisions with already placed
occ=set(); out=[[0]*C for _ in range(R)]
for cells in sorted(comps,key=lambda x:max(c for r,c in x),reverse=True):
 d=0
 while all(c+d+1<C and (r,c+d+1) not in occ for r,c in cells): d+=1
 moved=[(r,c+d) for r,c in cells]
 for r,c in moved:out[r][c]=grid[cells[0][0]][cells[0][1]];occ.add((r,c))
print(out)
